import json
schedule=[('cobalt',[0,1,2,3,4],1320,360),('reed',[0,2,4],1380,180),('plum',[1,3,5],30,150),('shell',[6],1350,90),('gold',[0],0,90),('elm',[5],60,180)]
jobs=[(1,29),(1,30),(1,150),(1,179),(1,180),(5,59),(5,60),(5,149),(5,150),(5,180),(6,1349),(6,1350),(0,0),(0,89),(0,90),(2,359),(2,360),(4,1380)]
def receive(d,m,fault=None):
    matches=[]
    for i,(r,days,s,e) in enumerate(schedule):
        duration=(e-s)%1440
        owner=d if s<e or m>=s else (d-1)%7
        if fault=='day_owner': owner=d
        covered=(s<=m<e) if s<e else (m>=s or m<e)
        if covered and owner in days: matches.append((duration,i,r))
    if not matches:return 'idle'
    return (min(matches,key=lambda x:x[1]) if fault=='first_match' else min(matches))[2]
def independent(d,m):
    t=d*1440+m
    choices=[]
    for i,(r,days,s,e) in enumerate(schedule):
        for day in days:
            for week in [-1,0,1]:
                start=(day+week*7)*1440+s
                duration=e-s if e>s else e+1440-s
                if start<=t<start+duration: choices.append((duration,i,r))
    return min(choices)[2] if choices else 'idle'
obj={'routes':[receive(d,m) for d,m in jobs], 'witnesses':{'day_owner':{'job':{'receiver':{'day':5,'minute':180}},'expected':'cobalt'},'first_match':{'job':{'receiver':{'day':1,'minute':30}},'expected':'plum'}}}
payload=json.dumps(obj,separators=(',',':'))
recovered=json.loads(payload)
assert set(recovered)=={'routes','witnesses'}
assert recovered['routes']==[independent(d,m) for d,m in jobs]
assert set(recovered['witnesses'])=={'day_owner','first_match'}
for name,w in recovered['witnesses'].items():
    assert set(w)=={'job','expected'} and set(w['job'])=={'receiver'}
    q=w['job']['receiver']; assert set(q)=={'day','minute'}
    d,m=q['day'],q['minute']; assert type(d)==int and 0<=d<=6 and type(m)==int and 0<=m<=1439
    assert receive(d,m)==independent(d,m)==w['expected']
    assert receive(d,m,name)!=w['expected']
    other='first_match' if name=='day_owner' else 'day_owner'
    assert receive(d,m,other)==w['expected']
